#include <furi.h>
#include <gui/gui.h> /* importing GUI function */

/* generated by fbt from .png files in images folder */
#include <pokegatchi_icons.h>

/* drawing canvas on screen stuff*/
static void draw_callback(Canvas* canvas, void* ctx) {
    UNUSED(ctx);
    canvas_draw_str(canvas, 10, 32, "Hello Pokegatchi!");
}

/* button stuff*/
static void input_callback(InputEvent* event, void* ctx) {
    bool* running = ctx;
    if(event->type == InputTypePress && event->key == InputKeyBack) {
        *running = false;
    }
}

int32_t pokegatchi_app(void* p) {
    UNUSED(p);
    bool running = true;

    ViewPort* view_port = view_port_alloc();
    view_port_draw_callback_set(view_port, draw_callback, NULL);
    view_port_input_callback_set(view_port, input_callback, &running);
    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, view_port, GuiLayerFullscreen);
    while(running) {
        furi_delay_ms(50);
    }
    gui_remove_view_port(gui, view_port);
    view_port_free(view_port);
    furi_record_close(RECORD_GUI);
    return 0;
}
